@inject IJSRuntime JS

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="message-area-header">
            <h2># @Channel.Name</h2>
            <p>@Channel.Description</p>
        </div>

        <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @foreach (var message in Messages)
            {
                <MessageBubble Message="message"
                               ThreadReplyCount="GetThreadReplyCount(message.Id)"
                               OnOpenThread="OnOpenThread"
                               OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <div class="message-input-area">
            <textarea @bind="newMessage" @bind:event="oninput"
                      placeholder="Type a message..."
                      @onkeydown="HandleKeyDown"></textarea>
            <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessage)">
                Send
            </button>
        </div>
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = new();

    [Parameter]
    public Channel? Channel { get; set; }

    [Parameter]
    public List<ThreadSummary> ThreadSummaries { get; set; } = new();

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;
    private string newMessage = string.Empty;

    private int GetThreadReplyCount(int messageId)
    {
        return ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId)?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessage)) return;
        var content = newMessage;
        newMessage = string.Empty;
        await OnSendMessage.InvokeAsync(content);
    }
}

