}

.channel-description {
    font-size: 0.75rem;
    color: #8d99ae;
    margin-top: 0.15rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
